//
// Hand-written TypeScript declarations for the Formulon WASM bindings.
//
// The entry point is `createFormulon`, the default and a named export of
// `@libraz/formulon` (single-threaded) and `@libraz/formulon/threads`
// (pthread); both share this surface. It resolves to the frozen `Formulon`
// object declared below.
//
// Mirror of the WASM module's registered bindings and of the pure-JS members
// and handle classes the npm package adds.
// Keep this file in sync when adding or removing bindings.

/// <reference lib="esnext.disposable" />

/** Discriminator of a {@link Value}. */
export const ValueKind: Readonly<{
  Blank: 0;
  Number: 1;
  Bool: 2;
  Text: 3;
  Error: 4;
  Array: 5;
  Ref: 6;
  Lambda: 7;
}>;
/** Union of the {@link ValueKind} ordinals. */
export type ValueKind = 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7;

